    i = [k for k, l in enumerate(lines) if re.match(r'^### ' + rid + r'\. ', l)][0]
    j = i + 1
    while not lines[j].startswith('### ') and not lines[j].startswith('## 4'):
        j += 1
    sec = lines[i+1:j]
    while sec and sec[0] == '': sec.pop(0)
    while sec and sec[-1] == '': sec.pop()
    return [l.replace('`', '') for l in sec]

def tail_bounds(rid):
    i = [k for k, l in enumerate(lines) if l.startswith('const ' + rid + '_TAIL = [')][0]
    j = i + 1
    while not lines[j].startswith('].join'):
        j += 1
    return i, j   # lines i+1 .. j-1 are the string lines

